import 'package:flutter/material.dart';import '../models/moment.dart';
class MomentFormSheet extends StatefulWidget{const MomentFormSheet({super.key});@override State<MomentFormSheet> createState()=>_S();}
class _S extends State<MomentFormSheet>{final f=GlobalKey<FormState>();String title='',note='';DateTime date=DateTime.now().add(const Duration(days:7));MomentType type=MomentType.event;
Future<void> pick()async{final r=await showDatePicker(context:context,initialDate:date,firstDate:DateTime(2000),lastDate:DateTime(2100));if(r!=null)setState(()=>date=r);}void submit(){if(!(f.currentState?.validate()??false))return;f.currentState!.save();final n=DateTime.now();Navigator.pop(context,Moment(id:n.microsecondsSinceEpoch.toString(),title:title,note:note,date:date,type:type,favorite:false,saved:true,createdAt:n));}
@override Widget build(BuildContext context)=>SafeArea(child:Padding(padding:EdgeInsets.fromLTRB(20,8,20,MediaQuery.viewInsetsOf(context).bottom+20),child:Form(key:f,child:ListView(shrinkWrap:true,children:[Text('Create a moment',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:18),TextFormField(autofocus:true,decoration:const InputDecoration(labelText:'Title',hintText:'Japan trip'),validator:(v)=>v==null||v.trim().isEmpty?'Add a title':null,onSaved:(v)=>title=v!.trim()),const SizedBox(height:12),TextFormField(maxLines:2,decoration:const InputDecoration(labelText:'Note (optional)'),onSaved:(v)=>note=v?.trim()??''),const SizedBox(height:12),DropdownButtonFormField<MomentType>(initialValue:type,decoration:const InputDecoration(labelText:'Type'),items:MomentType.values.map((e)=>DropdownMenuItem(value:e,child:Text(e.name))).toList(),onChanged:(v)=>setState(()=>type=v??type)),const SizedBox(height:12),OutlinedButton.icon(onPressed:pick,icon:const Icon(Icons.calendar_month_outlined),label:Text('${date.day}/${date.month}/${date.year}')),const SizedBox(height:18),FilledButton.icon(onPressed:submit,icon:const Icon(Icons.check_rounded),label:const Text('Create moment'))]))));}
